query FindManyCompanies($filter: CompanyFilterInput, $orderBy: [CompanyOrderByInput], $lastCursor: String, $limit: Int, $offset: Int) {
  companies(
    filter: $filter
    orderBy: $orderBy
    first: $limit
    after: $lastCursor
    offset: $offset
  ) {
    edges {
      node {
        __typename
        accountOwnerId
        address {
          addressStreet1
          addressStreet2
          addressCity
          addressState
          addressCountry
          addressPostcode
          addressLat
          addressLng
          __typename
        }
        annualRevenue {
          amountMicros
          currencyCode
          __typename
        }
        createdAt
        createdBy {
          source
          workspaceMemberId
          name
          context {
            provider
            applicationId
            __typename
          }
          __typename
        }
        deletedAt
        domainName {
          primaryLinkUrl
          primaryLinkLabel
          secondaryLinks {
            label
            url
            __typename
          }
          __typename
        }
        id
        linkedinLink {
          primaryLinkUrl
          primaryLinkLabel
          secondaryLinks {
            label
            url
            __typename
          }
          __typename
        }
        name
        position
        updatedAt
        updatedBy {
          source
          workspaceMemberId
          name
          context {
            provider
            applicationId
            __typename
          }
          __typename
        }
      }
      cursor
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      __typename
    }
    totalCount
    __typename
  }
}
